// Helper functions for filtering and organizing projects
export const getProjectsByCategory = (categoryId) => {
  return projects.filter(p => p.category === categoryId);
};

export const getProjectsByTag = (tag) => {
  return projects.filter(p => p.tags && p.tags.includes(tag));
};

export const getOperationalProjects = () => {
  return projects.filter(p => p.status === 'operational' || p.status === 'active' || p.status === 'connected');
};

export const getProjectsByAgent = (agent) => {
  return projects.filter(p => p.addedBy === agent);
};

export const getAllTags = () => {
  const tags = new Set();
  projects.forEach(p => {
    if (p.tags) {
      p.tags.forEach(tag => tags.add(tag));
    }
  });
  return Array.from(tags).sort();
};

// Function Zala uses to get active projects
export function getActiveProjects() {
  return projects.filter(p => p.status === "active" || p.status === "connected");
}

export default {
  projectCategories,
  projects,
  getProjectsByCategory,
  getProjectsByTag,
  getOperationalProjects,
  getProjectsByAgent,
  getAllTags,
  getActiveProjects
};
